using System.Threading.Channels;

public class EventProcessor : IAsyncDisposable
{
    private readonly Channel<string> _channel = Channel.CreateUnbounded<string>();
    private Task? _processingTask;

    public void Start()
    {
        _processingTask = Task.Run(RunLoopAsync);
    }

    private async Task RunLoopAsync()
    {
        await foreach (var item in _channel.Reader.ReadAllAsync())
        {
            Handle(item);
        }
    }

    public void Enqueue(string item)
    {
        if (!_channel.Writer.TryWrite(item))
            throw new InvalidOperationException("Channel is closed.");
    }

    public async ValueTask DisposeAsync()
    {
        _channel.Writer.Complete();

        if (_processingTask is not null)
        {
            // Graceful drain with timeout
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
            try
            {
                await _processingTask.WaitAsync(cts.Token);
            }
            catch (TimeoutException)
            {
                // Processing didn't finish in time — log and move on.
                // No Thread.Abort equivalent; the task will finish
                // when the current Handle() call completes.
            }
        }
    }

    private void Handle(string item) { /* your logic */ }
}
```

### If You Need Synchronous `Stop()` and `CancellationToken`

```csharp
public class EventProcessor : IDisposable
{
    private readonly Channel<string> _channel = Channel.CreateUnbounded<string>();
    private readonly CancellationTokenSource _cts = new();
    private Task? _processingTask;

    public void Start()
    {
        _processingTask = Task.Run(() => RunLoopAsync(_cts.Token));
    }

    private async Task RunLoopAsync(CancellationToken ct)
    {
        try
        {
            await foreach (var item in _channel.Reader.ReadAllAsync(ct))
            {
                Handle(item);
            }
        }
        catch (OperationCanceledException) { /* clean shutdown */ }
    }

    public void Enqueue(string item) => _channel.Writer.TryWrite(item);

    public void Stop()
    {
        _channel.Writer.Complete();
        _cts.Cancel();                             // unblocks ReadAllAsync immediately
        _processingTask?.Wait(TimeSpan.FromSeconds(5));
    }

    public void Dispose()
    {
        Stop();
        _cts.Dispose();
    }

    private void Handle(string item) { /* your logic */ }
}
```

### Key Migration Pitfalls

1. **No `Thread.Abort` replacement** — there is no way to forcibly kill work in .NET 8. If `Handle()` can hang, build cancellation *into* `Handle()` itself via `CancellationToken`.

2. **`Channel<T>` replaces the manual `Queue` + `lock` + `ManualResetEvent`** triple. It's thread-safe, allocation-free on the hot path, and handles backpressure (`CreateBounded`).

3. **`Writer.Complete()`** signals the reader to drain and exit — this is the clean replacement for `Thread.Interrupt`.

4. **Don't fire-and-forget `Task.Run`** — always store the `Task` and observe it in `Dispose`/`DisposeAsync` to surface exceptions.

5. **Bounded channels** (`Channel.CreateBounded<string>(capacity)`) should be preferred in production to prevent unbounded memory growth.
